```
from datamodel import Order

TARGET_SYMBOL = "TOMATOES"
TARGET_TIMESTAMP = 27_300
TARGET_PRICE = 4_992
TARGET_QUANTITY = -5


class Trader:
    def run(self, state):
        if state.timestamp != TARGET_TIMESTAMP:
            return {}, 0, state.traderData

        if TARGET_SYMBOL not in state.order_depths:
            return {}, 0, state.traderData

        orders = {
            TARGET_SYMBOL: [Order(TARGET_SYMBOL, TARGET_PRICE, TARGET_QUANTITY)],
        }
        return orders, 0, state.traderData
```
